-- Journeys build plan J4 — step 1, requirements: the brief, the payment plan,
-- phases that belong to a contract, and the flags that make money and
-- commitments routable. Generated by `prisma migrate diff`, then hand-extended:
-- the phase backfill, the two hand-written CHECKs on ContractBrief, the two on
-- PlannedInvoice, the partial unique index on Dependency, and the sensitive-
-- article backfill.

-- CreateEnum
CREATE TYPE "BriefKind" AS ENUM ('NEW_SITE', 'FEATURE_FOR_EXISTING');

-- CreateEnum
CREATE TYPE "DesignTier" AS ENUM ('THEME_PICK', 'CLAUDE_ASSISTED', 'SENIOR_DESIGNER');

-- CreateEnum
CREATE TYPE "PaymentSplit" AS ENUM ('LUMP_SUM', 'INSTALLMENTS', 'MONTHLY');

-- DropIndex
DROP INDEX "Phase_projectId_number_key";

-- AlterTable
ALTER TABLE "Article" ADD COLUMN     "sensitive" BOOLEAN NOT NULL DEFAULT false;

-- AlterTable
ALTER TABLE "Dependency" ADD COLUMN     "briefKey" TEXT,
ADD COLUMN     "technical" BOOLEAN NOT NULL DEFAULT false;

-- AlterTable: contractId lands nullable, is backfilled below, and only then
-- becomes required (as schema.prisma says).
ALTER TABLE "Phase" ADD COLUMN     "contractId" TEXT,
ADD COLUMN     "plannedEndAt" DATE;

-- BACKFILL:BEGIN
-- Hand-written. `j4.test.ts` extracts everything between the BEGIN and END
-- markers and runs it over fixture rows inside a rolled-back transaction; keep
-- every statement of the backfill inside them, and keep it to UPDATEs.
--
-- Every existing phase gets its project's primary contract: the earliest by
-- `createdAt`, `id` breaking a tie — exactly `primaryContractId`
-- (resolvers/admin/shared.ts), which is also who owned a project's phases
-- before this stage (`ownsProjectWork`). A phase on a project with no contract
-- is left NULL, and the guard below refuses to go on.
UPDATE "Phase" AS p
SET "contractId" = (
  SELECT c."id"
  FROM "Contract" AS c
  WHERE c."projectId" = p."projectId"
  ORDER BY c."createdAt" ASC, c."id" ASC
  LIMIT 1
);

-- The template's two money articles (PD-14): *Fees* and *Payment Schedule*, by
-- the number and the title `lib/templates.ts`'s ARTICLES gives them. Matching
-- the title too keeps a hand-numbered contract's unrelated article 4 or 5 out.
UPDATE "Article"
SET "sensitive" = true
WHERE ("number" = 4 AND "titleEn" = 'Fees')
   OR ("number" = 5 AND "titleEn" = 'Payment Schedule');
-- BACKFILL:END

-- A phase no contract can own would be silently unreachable from every wizard;
-- refuse rather than guess. Same shape as J2's guard, and likewise run over a
-- fixture by `j4.test.ts`.
-- VERIFY:BEGIN
DO $$
DECLARE orphans integer;
BEGIN
  SELECT count(*) INTO orphans FROM "Phase" WHERE "contractId" IS NULL;
  IF orphans > 0 THEN
    RAISE EXCEPTION 'J4: % phase(s) are on a project with no contract; give each project a contract before making Phase.contractId required', orphans;
  END IF;
END $$;
-- VERIFY:END

ALTER TABLE "Phase" ALTER COLUMN "contractId" SET NOT NULL;

