-- Hand-written: what Prisma cannot say. Each is proven by a direct insert in
-- `j4.test.ts`, not only through a resolver.

-- The ideal deadline is not after the hard one. NULL on either side makes the
-- comparison NULL, which a CHECK passes — "when both set", as intended.
ALTER TABLE "ContractBrief"
  ADD CONSTRAINT "ContractBrief_deadlines_ordered" CHECK ("idealDeadline" <= "hardDeadline");

-- Every allowance that is set is above zero (an unset one passes, as above).
ALTER TABLE "ContractBrief"
  ADD CONSTRAINT "ContractBrief_allowances_positive" CHECK (
    "premadeRounds" > 0 AND "wireframeIterations" > 0 AND "mockupIterations" > 0 AND "demoIterationsPerPhase" > 0
  );

-- A planned invoice is for something, and is due on or after it is issued.
ALTER TABLE "PlannedInvoice"
  ADD CONSTRAINT "PlannedInvoice_amount_positive" CHECK ("amount" > 0);
ALTER TABLE "PlannedInvoice"
  ADD CONSTRAINT "PlannedInvoice_term_not_negative" CHECK ("paymentTermDays" >= 0);

-- One row per commitment key per project — a partial index, because a plain
-- unique would treat every NULL `briefKey` (an ordinary board row) as distinct
-- from every other, which is exactly what is wanted for them and exactly what
-- Prisma's `@@unique` cannot be told to do only for the non-NULL ones.
CREATE UNIQUE INDEX "Dependency_briefKey_key" ON "Dependency"("projectId", "briefKey") WHERE "briefKey" IS NOT NULL;
